import pandas as pd


def run(inputs: dict) -> dict:
    target = inputs["target_snapshot"].copy()
    cdc = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Determine watermark high_ts
    if len(watermark) > 0:
        high_ts = watermark["high_ts"].iloc[0]
    else:
        high_ts = pd.NaT

    # Step 1: keep only events strictly after watermark
    if pd.notna(high_ts):
        cdc = cdc[cdc["event_ts"] > high_ts]
    else:
        # if watermark is null/missing, treat as no filtering (all events are "after")
        cdc = cdc[cdc["event_ts"].notna() | cdc["event_ts"].isna()]

    # Step 2: per product_id, pick latest event by (event_ts, event_seq)
    if len(cdc) > 0:
        cdc_sorted = cdc.sort_values(
            by=["product_id", "event_ts", "event_seq"],
            ascending=[True, True, True],
        )
        latest = cdc_sorted.groupby("product_id", as_index=False).tail(1)
    else:
        latest = cdc.copy()

    # Build target snapshot as dict keyed by product_id for easy upsert/delete
    target_indexed = target.set_index("product_id", drop=False)
    target_dict = {}
    for pid, row in target_indexed.iterrows():
        target_dict[pid] = {
            "product_id": row["product_id"],
            "name": row["name"],
            "price": row["price"],
            "last_event_ts": row["last_event_ts"],
        }

    # Step 3 & 4: apply latest events
    for _, ev in latest.iterrows():
        pid = ev["product_id"]
        op = ev["op"]
        if op == "D":
            if pid in target_dict:
                del target_dict[pid]
        elif op in ("I", "U"):
            target_dict[pid] = {
                "product_id": pid,
                "name": ev["name"],
                "price": ev["price"],
                "last_event_ts": ev["event_ts"],
            }
        # unknown ops ignored

    if len(target_dict) > 0:
        result = pd.DataFrame(list(target_dict.values()))
        result = result[["product_id", "name", "price", "last_event_ts"]]
        result["product_id"] = result["product_id"].astype("int64")
        result["price"] = result["price"].astype("float64")
        result["last_event_ts"] = pd.to_datetime(result["last_event_ts"])
    else:
        result = pd.DataFrame(
            {
                "product_id": pd.Series(dtype="int64"),
                "name": pd.Series(dtype="object"),
                "price": pd.Series(dtype="float64"),
                "last_event_ts": pd.Series(dtype="datetime64[us]"),
            }
        )

    return {"new_snapshot": result}
